module tower_coverage(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [15:0] x0, y0, x1, y1, x2, y2, x3, y3,\n    input wire [15:0] x4, y4, x5, y5, x6, y6, x7, y7,\n    output reg [7:0] result,\n    output reg done\n);\n\n    parameter COORD_WIDTH = 16;\n    parameter SQ_DIST_THRESH = 262144; // 4 * 256 * 256 = 4 * 65536\n    parameter MAX_TOWERS = 8;\n    parameter MAX_RESULT = 9;\n\n    // State definitions\n    localparam [2:0] S_IDLE = 3'd0;\n    localparam [2:0] S_RESET = 3'd1;\n    localparam [2:0] S_COMPUTE_DIST = 3'd2;\n    localparam [2:0] S_BUILD_COMPONENTS = 3'd3;\n    localparam [2:0] S_ASSIGN_COMPONENTS = 3'd4;\n    localparam [2:0] S_COMPUTE_MIN_DIST = 3'd5;\n    localparam [2:0] S_EVALUATE = 3'd6;\n    localparam [2:0] S_DONE = 3'd7;\n\n    reg [2:0] state, next_state;\n\n    // Storage for coordinates\n    reg [COORD_WIDTH-1:0] x_reg [0:MAX_TOWERS-1];\n    reg [COORD_WIDTH-1:0] y_reg [0:MAX_TOWERS-1];\n\n    // Union-Find arrays\n    reg [2:0] parent [0:MAX_TOWERS-1];\n    reg [3:0] size [0:MAX_TOWERS-1]; // component size\n\n    // Component assignment\n    reg [2:0] comp_id [0:MAX_TOWERS-1];\n    reg [3:0] comp_size [0:MAX_TOWERS-1]; // size per component\n    reg [3:0] num_components;\n\n    // Pairwise distance matrix (store only when needed)\n    reg [31:0] dist_sq [0:MAX_TOWERS-1][0:MAX_TOWERS-1];\n    reg edge_exists [0:MAX_TOWERS-1][0:MAX_TOWERS-1];\n\n    // Temporary variables for loops\n    reg [3:0] i, j, k, m, n_idx;\n    reg [31:0] dx, dy, dx_sq, dy_sq;\n    reg [31:0] min_dist_sq;\n    reg [7:0] current_max;\n    reg [7:0] temp_total;\n    reg found_root;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        case (state)\n            S_IDLE: begin\n                if (start) next_state = S_RESET;\n                else next_state = S_IDLE;\n            end\n            S_RESET: next_state = S_COMPUTE_DIST;\n            S_COMPUTE_DIST: begin\n                if (i >= n_idx && j >= n_idx) next_state = S_BUILD_COMPONENTS;\n                else next_state = S_COMPUTE_DIST;\n            end\n            S_BUILD_COMPONENTS: begin\n                if (i >= n_idx && j >= n_idx) next_state = S_ASSIGN_COMPONENTS;\n                else next_state = S_BUILD_COMPONENTS;\n            end\n            S_ASSIGN_COMPONENTS: next_state = S_COMPUTE_MIN_DIST;\n            S_COMPUTE_MIN_DIST: begin\n                if (i >= num_components && j >= num_components) next_state = S_EVALUATE;\n                else next_state = S_COMPUTE_MIN_DIST;\n            end\n            S_EVALUATE: next_state = S_DONE;\n            S_DONE: next_state = S_DONE;\n            default: next_state = S_IDLE;\n        endcase\n    end\n\n    // Main computation logic\n    always @(posedge clk) begin\n        if (state == S_RESET) begin\n            // Initialize coordinates from inputs\n            x_reg[0] <= x0; y_reg[0] <= y0;\n            x_reg[1] <= x1; y_reg[1] <= y1;\n            x_reg[2] <= x2; y_reg[2] <= y2;\n            x_reg[3] <= x3; y_reg[3] <= y3;\n            x_reg[4] <= x4; y_reg[4] <= y4;\n            x_reg[5] <= x5; y_reg[5] <= y5;\n            x_reg[6] <= x6; y_reg[6] <= y6;\n            x_reg[7] <= x7; y_reg[7] <= y7;\n            n_idx <= n;\n            // Initialize union-find\n            for (i = 0; i < MAX_TOWERS; i = i + 1) begin\n                parent[i] <= i;\n                size[i] <= 4'd1;\n                comp_id[i] <= 3'd0;\n                comp_size[i] <= 4'd0;\n            end\n            // Reset distance matrix flags\n            for (i = 0; i < MAX_TOWERS; i = i + 1) begin\n                for (j = 0; j < MAX_TOWERS; j = j + 1) begin\n                    edge_exists[i][j] <= 1'b0;\n                    dist_sq[i][j] <= 32'd0;\n                end\n            end\n            i <= 4'd0;\n            j <= 4'd0;\n            num_components <= 4'd0;\n            current_max <= 8'd0;\n            temp_total <= 8'd0;\n        end\n        else if (state == S_COMPUTE_DIST) begin\n            // Compute pairwise distances and store edges\n            if (i < n_idx) begin\n                if (j < n_idx) begin\n                    if (i != j) begin\n                        dx <= (x_reg[i] > x_reg[j]) ? (x_reg[i] - x_reg[j]) : (x_reg[j] - x_reg[i]);\n                        dy <= (y_reg[i] > y_reg[j]) ? (y_reg[i] - y_reg[j]) : (y_reg[j] - y_reg[i]);\n                        dx_sq <= dx * dx;\n                        dy_sq <= dy * dy;\n                        dist_sq[i][j] <= dx_sq + dy_sq;\n                        if (dx_sq + dy_sq <= SQ_DIST_THRESH) begin\n                            edge_exists[i][j] <= 1'b1;\n                            edge_exists[j][i] <= 1'b1;\n                        end\n                    end\n                    j <= j + 4'd1;\n                end else begin\n                    j <= 4'd0;\n                    i <= i + 4'd1;\n                end\n            end\n        end\n        else if (state == S_BUILD_COMPONENTS) begin\n            // Process edges to union components\n            if (i < n_idx) begin\n                if (j < n_idx) begin\n                    if (edge_exists[i][j]) begin\n                        // Perform union of i and j\n                        // Find root of i\n                        k <= i;\n                        while (parent[k] != k) begin\n                            k <= parent[k];\n                        end\n                        // Find root of j\n                        m <= j;\n                        while (parent[m] != m) begin\n                            m <= parent[m];\n                        end\n                        // Union by size\n                        if (k != m) begin\n                            if (size[k] < size[m]) begin\n                                parent[k] <= m;\n                                size[m] <= size[m] + size[k];\n                            end else begin\n                                parent[m] <= k;\n                                size[k] <= size[k] + size[m];\n                            end\n                        end\n                    end\n                    j <= j + 4'd1;\n                end else begin\n                    j <= 4'd0;\n                    i <= i + 4'd1;\n                end\n            end\n        end\n        else if (state == S_ASSIGN_COMPONENTS) begin\n            // Assign component IDs and compute sizes\n            num_components <= 4'd0;\n            for (i = 0; i < n_idx; i = i + 1) begin\n                // Find root of i\n                k <= i;\n                while (parent[k] != k) begin\n                    k <= parent[k];\n                end\n                // Check if this root has been assigned an ID\n                found_root <= 1'b0;\n                for (m = 0; m < num_components; m = m + 1) begin\n                    if (comp_id[m] == k) begin\n                        comp_size[m] <= comp_size[m] + 4'd1;\n                        found_root <= 1'b1;\n                    end\n                end\n                if (!found_root) begin\n                    comp_id[num_components] <= k;\n                    comp_size[num_components] <= 4'd1;\n                    num_components <= num_components + 4'd1;\n                end\n            end\n            i <= 4'd0;\n            j <= 4'd0;\n        end\n        else if (state == S_COMPUTE_MIN_DIST) begin\n            // Compute minimum distance between each pair of components\n            if (i < num_components) begin\n                if (j < num_components) begin\n                    if (i != j) begin\n                        // Compute min distance between any tower in component i and any in component j\n                        min_dist_sq <= 32'd4294967295; // Initialize to large value\n                        for (m = 0; m < n_idx; m = m + 1) begin\n                            for (k = 0; k < n_idx; k = k + 1) begin\n                                // Check if m is in component i and k in component j\n                                // Find root of m\n                                n_idx <= m;\n                                while (parent[n_idx] != n_idx) begin\n                                    n_idx <= parent[n_idx];\n                                end\n                                // Find root of k\n                                n_idx <= k;\n                                while (parent[n_idx] != n_idx) begin\n                                    n_idx <= parent[n_idx];\n                                end\n                                if (comp_id[m] == comp_id[i] && comp_id[k] == comp_id[j]) begin\n                                    if (dist_sq[m][k] < min_dist_sq) begin\n                                        min_dist_sq <= dist_sq[m][k];\n                                    end\n                                end\n                            end\n                        end\n                        // If min_dist_sq <= SQ_DIST_THRESH, then components can be connected\n                        if (min_dist_sq <= SQ_DIST_THRESH) begin\n                            temp_total <= comp_size[i] + comp_size[j] + 8'd1;\n                            if (temp_total > current_max) current_max <= temp_total;\n                        end\n                    end\n                    j <= j + 4'd1;\n                end else begin\n                    j <= 4'd0;\n                    i <= i + 4'd1;\n                end\n            end\n        end\n        else if (state == S_EVALUATE) begin\n            // Also consider connecting a single component (size + 1)\n            for (i = 0; i < num_components; i = i + 1) begin\n                temp_total <= comp_size[i] + 8'd1;\n                if (temp_total > current_max) current_max <= temp_total;\n            end\n            result <= current_max;\n        end\n        else if (state == S_DONE) begin\n            done <= 1'b1;\n        end\n    end\n\nendmodule